<?php
declare(strict_types=1); require_once __DIR__ . '/../includes/auth.php'; require_auth(); require_once __DIR__ . '/../includes/csrf.php'; require_once __DIR__ . '/../config/database.php'; require_csrf();
$tracking=post_string('tracking',15);$remarks=post_string('remarks',500);$userId=(int)$_SESSION['user_id'];$document=document_by_tracking($conn,$tracking);$route=current_route($conn,$tracking);if(!$document||!$route||(int)$route['receiver']!==$userId||$document['status']!=='open'){flash('error','This document cannot be closed.');redirect('dashboard.php');}$conn->begin_transaction();try{$now=date('Y-m-d H:i:s');$status='Closed';$previousSender=(int)$route['sender'];$log=$conn->prepare('INSERT INTO dr_logs (id_track,sender,receiver,status,date,remarks) VALUES (?,?,?,?,?,?)');$log->bind_param('siisss',$tracking,$userId,$previousSender,$status,$now,$remarks);$log->execute();$closed='closed';$update=$conn->prepare('UPDATE dr_documents SET status=? WHERE id_track=?');$update->bind_param('ss',$closed,$tracking);$update->execute();$conn->commit();flash('success','Document closed.');redirect('documents/view.php?tracking='.rawurlencode($tracking));}catch(Throwable $error){$conn->rollback();error_log($error->getMessage());flash('error','Unable to close the document.');redirect('dashboard.php');}
